// Conditional on draft: with the row lock taken first, this cannot run twice for one challan.
func (q *Queries) ReleaseChallan(ctx context.Context, arg ReleaseChallanParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, releaseChallan,
		arg.ChallanNo,
		arg.ConsumerNo,
		arg.ReleasedBy,
		arg.TenantID,
		arg.ID,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const voidChallan = `-- name: VoidChallan :one
UPDATE challans
SET status = 'void', void_reason = $1, voided_at = now()
WHERE tenant_id = $2 AND id = $3 AND status = 'draft'
RETURNING id
`

type VoidChallanParams struct {
	Reason   pgtype.Text
	TenantID pgtype.UUID
	ID       pgtype.UUID
}

func (q *Queries) VoidChallan(ctx context.Context, arg VoidChallanParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, voidChallan, arg.Reason, arg.TenantID, arg.ID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const voidPayment = `-- name: VoidPayment :execrows
UPDATE payments
SET status = 'voided', void_reason = $1, voided_at = now(), voided_by = $2,
    void_entry_id = $3
WHERE tenant_id = $4 AND id = $5 AND status = 'recorded'
`

type VoidPaymentParams struct {
	Reason      pgtype.Text
	VoidedBy    pgtype.UUID
	VoidEntryID pgtype.UUID
	TenantID    pgtype.UUID
	ID          pgtype.UUID
}

// Conditional on recorded: with the row lock taken first this runs once per payment.
func (q *Queries) VoidPayment(ctx context.Context, arg VoidPaymentParams) (int64, error) {
	result, err := q.db.Exec(ctx, voidPayment,
		arg.Reason,
		arg.VoidedBy,
		arg.VoidEntryID,
		arg.TenantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
